    private LinearLayout landscapeSources;
    private void refreshSourceTabs(){if(landscapeSources==null)return;landscapeSources.removeAllViews();for(PluginManager.PluginInfo p:pluginManager.list()){if(!p.enabled)continue;Button button=landscapeButton(p.name);button.setTextColor(p.id.equals(landscapeSource)?Color.rgb(220,170,255):Color.LTGRAY);landscapeSources.addView(button,new LinearLayout.LayoutParams(dp(112),dp(38)));button.setOnClickListener(v->{landscapeSource=p.id;prefs.edit().putString("selected_source",p.id).apply();refreshSourceTabs();});}if(landscapeSources.getChildCount()==0){Button button=landscapeButton("安装音乐源");landscapeSources.addView(button);button.setOnClickListener(v->showPluginMarket());}}
    private void refreshLandscapeGrid(){if(landscapeGrid==null)return;landscapeGrid.removeAllViews();if(names.isEmpty()){landscapeGrid.addView(text("暂无歌曲，先搜索在线音乐或添加本地文件",17,Color.rgb(190,185,195)),new LinearLayout.LayoutParams(-1,dp(80)));return;}LinearLayout row=null;int count=0;for(int i=0;i<names.size()&&i<60;i++){if(count%4==0){row=new LinearLayout(this);row.setPadding(0,dp(4),0,dp(4));landscapeGrid.addView(row,new LinearLayout.LayoutParams(-1,dp(150)));}LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(8),dp(6),dp(8),dp(6));card.setBackground(bg(Color.rgb(37,33,42),12));TextView cover=text("♪",32,Color.rgb(200,170,235));cover.setGravity(Gravity.CENTER);card.addView(cover,new LinearLayout.LayoutParams(-1,dp(92)));TextView title=text(names.get(i),13,Color.WHITE);title.setMaxLines(2);card.addView(title,new LinearLayout.LayoutParams(-1,dp(42)));final int index=i;card.setOnClickListener(v->playIndex(index));row.addView(card,new LinearLayout.LayoutParams(0,dp(142),1));count++;}}
    private void landscapeSearch(String q){if(q.isEmpty()){refreshLandscapeGrid();return;}if(landscapeSource.isEmpty()){ArrayList<PluginManager.PluginInfo> installed=pluginManager.list();if(installed.isEmpty()){showPluginError("先安装并启用一个音乐源插件");showPlugins();return;}landscapeSource=installed.get(0).id;}final String source=landscapeSource;PluginManager.PluginInfo chosen=null;for(PluginManager.PluginInfo p:pluginManager.list())if(p.id.equals(source))chosen=p;final PluginManager.PluginInfo selected=chosen;if(selected==null)return;Toast.makeText(this,"正在搜索 "+selected.name,Toast.LENGTH_SHORT).show();pluginManager.searchSource(source,q,(ok,value)->runOnUiThread(()->showPluginTrackResult(selected,"搜索结果",ok,value)));}
    private void updateModes(){ if(shuffleButton!=null)shuffleButton.setText(shuffle?"随机开":"随机"); if(repeatButton!=null)repeatButton.setText(repeat?"循环开":"循环"); }
    private void restoreSession(){String uri=prefs.getString("last_uri","");if(uri.isEmpty())return;for(int i=0;i<tracks.size();i++){if(tracks.get(i).toString().equals(uri)){resumeIndex=i;resumePosition=Math.max(0,prefs.getInt("last_pos",0));current=i;nowPlaying.setText(names.get(i));loadCover(tracks.get(i));if(playButton!=null)playButton.setText("继续");break;}}}
    private void saveSession(){if(player!=null&&current>=0&&current<tracks.size()){try{prefs.edit().putString("last_uri",tracks.get(current).toString()).putInt("last_pos",player.getCurrentPosition()).apply();}catch(Exception ignored){}}}
    private void pickAudio(){ Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT); i.setType("audio/*"); i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true); i.addCategory(Intent.CATEGORY_OPENABLE); i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION); startActivityForResult(i,PICK_AUDIO); }
    @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c==RESULT_OK&&d!=null&&r==EXPORT_DATA){writeBackup(d.getData());return;}if(c==RESULT_OK&&d!=null&&r==IMPORT_DATA){readBackup(d.getData());return;}if(c==RESULT_OK&&d!=null&&r==PICK_LRC){readLocalLyrics(d.getData());return;}if(r!=PICK_AUDIO||c!=RESULT_OK||d==null)return;try{if(d.getClipData()!=null){for(int i=0;i<d.getClipData().getItemCount();i++){Uri u=d.getClipData().getItemAt(i).getUri();persist(u);add(u);}}else if(d.getData()!=null){persist(d.getData());add(d.getData());}}catch(Exception ignored){}adapter.notifyDataSetChanged();refreshLandscapeGrid(); if(headingView!=null)headingView.setText("本地歌曲  ·  "+names.size());}
    private void persist(Uri u){try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}}
    private void loadLibrary(){StringJoiner us=new StringJoiner("\n");String raw=prefs.getString("uris","");String ns=prefs.getString("names","");if(raw.isEmpty())return;String[] a=raw.split("\\n",-1),b=ns.split("\\n",-1);for(int i=0;i<a.length;i++)try{tracks.add(Uri.parse(a[i]));if(a[i].startsWith("plugin:")){Uri pu=Uri.parse(a[i]);pluginTrackRefs.put(a[i],pu.getAuthority()+"\n"+pu.getQueryParameter("id"));}names.add(i<b.length?b[i]:a[i]);}catch(Exception ignored){}}
    private void saveLibrary(){StringJoiner u=new StringJoiner("\n"),n=new StringJoiner("\n");for(Uri x:tracks)u.add(x.toString());for(String x:names)n.add(x);prefs.edit().putString("uris",u.toString()).putString("names",n.toString()).apply();}
    private void removeTrack(int i){if(i<0||i>=tracks.size())return; if(current==i){if(player!=null){player.stop();player.release();player=null;}current=-1;nowPlaying.setText("尚未选择歌曲");playButton.setText("播放");} tracks.remove(i); names.remove(i); saveLibrary(); adapter.notifyDataSetChanged();refreshLandscapeGrid(); if(headingView!=null)headingView.setText("本地歌曲  ·  "+names.size()); Toast.makeText(this,"已移除歌曲",Toast.LENGTH_SHORT).show();}
    private void loadLiked(){String raw=prefs.getString("liked",""); if(!raw.isEmpty()) liked.addAll(Arrays.asList(raw.split("\n")));}
    private void saveLiked(){StringJoiner j=new StringJoiner("\n"); for(String x:liked)j.add(x); prefs.edit().putString("liked",j.toString()).apply();}
    private void updateLike(){if(likeButton!=null&&current>=0&&current<tracks.size())likeButton.setText(liked.contains(tracks.get(current).toString())?"♥":"♡");}
    private void toggleLocalLike(String key){if(liked.contains(key))liked.remove(key);else liked.add(key);saveLiked();updateLike();}
    private void toggleLike(){if(current<0||current>=tracks.size()){Toast.makeText(this,"请先播放一首歌曲",Toast.LENGTH_SHORT).show();return;} String key=tracks.get(current).toString();Uri uri=tracks.get(current);if("plugin".equals(uri.getScheme())){try{pluginManager.export(uri.getAuthority(),"like",new JSONObject().put("id",uri.getQueryParameter("id")).put("on",!liked.contains(key)),(ok,raw)->runOnUiThread(()->{if(ok){toggleLocalLike(key);Toast.makeText(this,"来源收藏已更新",Toast.LENGTH_SHORT).show();}else showPluginError(raw);}));}catch(Exception e){showPluginError("收藏参数错误");}}else toggleLocalLike(key);}

    private void showFavorites(){ArrayList<String> favNames=new ArrayList<>(); ArrayList<Integer> indexes=new ArrayList<>(); for(int i=0;i<tracks.size();i++)if(liked.contains(tracks.get(i).toString())){favNames.add(names.get(i));indexes.add(i);} if(favNames.isEmpty()){Toast.makeText(this,"还没有收藏歌曲",Toast.LENGTH_SHORT).show();return;} ListView lv=new ListView(this); ArrayAdapter<String> a=new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,favNames); lv.setAdapter(a); AlertDialog dialog=new AlertDialog.Builder(this).setTitle("我的收藏").setView(lv).setNegativeButton("关闭",null).create(); lv.setOnItemClickListener((p,v,pos,id)->{dialog.dismiss();playIndex(indexes.get(pos));}); dialog.show();}
    private void loadPlaylists(){try{JSONObject all=new JSONObject(prefs.getString("playlists","{}")); java.util.Iterator<String> it=all.keys(); while(it.hasNext()){String n=it.next(); JSONArray a=all.getJSONArray(n); HashSet<String> set=new HashSet<>(); for(int i=0;i<a.length();i++)set.add(a.getString(i)); playlists.put(n,set);}}catch(Exception ignored){}}
    private void savePlaylists(){try{JSONObject all=new JSONObject(); for(String n:playlists.keySet()){JSONArray a=new JSONArray(); for(String u:playlists.get(n))a.put(u); all.put(n,a);} prefs.edit().putString("playlists",all.toString()).apply();}catch(Exception ignored){}}
    private void showBackup(){new AlertDialog.Builder(this).setTitle("备份与恢复").setMessage("导出或导入本地账号数据。音乐文件本身不会被复制。\n\n包含：音乐库、收藏、歌单、最近播放、评论和昵称。").setPositiveButton("导出",(d,w)->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"mygo-music-backup.json");startActivityForResult(i,EXPORT_DATA);}).setNeutralButton("导入",(d,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT_DATA);}).setNegativeButton("关闭",null).show();}
    private String backupJson(){try{JSONObject o=new JSONObject();for(String k:new String[]{"uris","names","liked","playlists","recent","comments","account_name","local_lyrics"})o.put(k,prefs.getString(k,""));return o.toString(2);}catch(Exception e){return "{}";}}
    private void writeBackup(Uri u){try{OutputStream out=getContentResolver().openOutputStream(u);out.write(backupJson().getBytes("UTF-8"));out.close();Toast.makeText(this,"备份已导出",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"导出失败",Toast.LENGTH_SHORT).show();}}
    private void readBackup(Uri u){try{InputStream in=getContentResolver().openInputStream(u);ByteArrayOutputStream buf=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))>0)buf.write(b,0,n);in.close();JSONObject o=new JSONObject(new String(buf.toByteArray(),"UTF-8"));SharedPreferences.Editor e=prefs.edit();for(String k:new String[]{"uris","names","liked","playlists","recent","comments","account_name","local_lyrics"})if(o.has(k))e.putString(k,o.optString(k,""));e.apply();Toast.makeText(this,"备份已导入，正在刷新",Toast.LENGTH_SHORT).show();recreate();}catch(Exception e){Toast.makeText(this,"导入失败，文件格式不正确",Toast.LENGTH_SHORT).show();}}
    private void showNowPlaying(){if(current<0||current>=names.size()){Toast.makeText(this,"请先播放一首歌曲",Toast.LENGTH_SHORT).show();return;} LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),dp(12),dp(20),dp(8));ImageView image=new ImageView(this);image.setImageDrawable(coverArt.getDrawable());image.setScaleType(ImageView.ScaleType.CENTER_CROP);box.addView(image,new LinearLayout.LayoutParams(-1,dp(260)));TextView title=text(names.get(current),19,Color.WHITE);title.setPadding(0,dp(14),0,dp(8));box.addView(title,new LinearLayout.LayoutParams(-1,dp(48)));TextView hint=text("正在播放",13,Color.rgb(180,170,190));box.addView(hint,new LinearLayout.LayoutParams(-1,dp(28)));new AlertDialog.Builder(this).setTitle("正在播放").setView(box).setPositiveButton("歌词",(d,w)->showLyrics()).setNeutralButton("评论",(d,w)->showComments()).setNegativeButton("关闭",null).show();}
    private void showPlugins(){
        ArrayList<PluginManager.PluginInfo> infos=pluginManager.list();
        ArrayList<String> rows=new ArrayList<>();
        for(PluginManager.PluginInfo p:infos) rows.add((p.enabled?"已启用  ":"已停用  ")+p.summary());
        if(rows.isEmpty()) rows.add("暂无插件");
        ListView lv=new ListView(this);
        lv.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,rows));
        AlertDialog d=new AlertDialog.Builder(this).setTitle("插件").setView(lv).setPositiveButton("安装 GitHub 插件",null).setNeutralButton("插件市场",null).setNegativeButton("关闭",null).create();
        lv.setOnItemClickListener((parent,v,pos,id)->{
            if(pos>=infos.size()) return;
            d.dismiss();
            showPluginDetail(infos.get(pos));
        });
        d.setOnShowListener(x->{
            d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{
                final EditText input=new EditText(this);
                input.setSingleLine(true);
                input.setHint("owner/repo 或 GitHub 地址");
                AlertDialog install=new AlertDialog.Builder(this).setTitle("安装插件").setView(input).setNegativeButton("取消",null).setPositiveButton("安装",(a,b)->{
                    Toast.makeText(this,"正在安装插件…",Toast.LENGTH_SHORT).show();
                    pluginManager.installFromGitHub(input.getText().toString(),(ok,msg)->runOnUiThread(()->{
                        Toast.makeText(this,msg,Toast.LENGTH_LONG).show();
                        if(ok){refreshSourceTabs();showPlugins();}
                    }));
                }).create();
                install.show();
            });
            d.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v->{d.dismiss();showPluginMarket();});
        });
        d.show();
    }
    private void showPluginMarket(){
        ArrayList<String[]> data=new ArrayList<>();JSONArray catalog=pluginManager.marketSnapshot();for(int i=0;i<catalog.length();i++){JSONObject item=catalog.optJSONObject(i);if(item!=null)data.add(new String[]{item.optString("name"),item.optString("repo"),item.optString("description"),item.isNull("stars")?"":item.optString("stars","")});}ArrayList<View> cards=new ArrayList<>();

        LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(12),dp(8),dp(12),dp(8));
        EditText filter=new EditText(this);filter.setSingleLine(true);filter.setHint("搜索 "+data.size()+" 个插件");list.addView(filter);
        for(String[] item:data){
            LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(16),dp(14),dp(16),dp(14));card.setBackground(bg(Color.rgb(35,29,43),18));
            LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(226));cp.setMargins(0,dp(7),0,dp(7));list.addView(card,cp);cards.add(card);
            LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);
            TextView icon=text(item[0].substring(0,1).toUpperCase(),24,Color.WHITE);icon.setGravity(Gravity.CENTER);icon.setBackground(bg(Color.rgb(119,78,151),18));header.addView(icon,new LinearLayout.LayoutParams(dp(56),dp(56)));
            LinearLayout titleBox=new LinearLayout(this);titleBox.setOrientation(LinearLayout.VERTICAL);titleBox.setPadding(dp(12),0,dp(4),0);TextView name=text(item[0],20,Color.WHITE);name.setTypeface(null,1);titleBox.addView(name,new LinearLayout.LayoutParams(-1,dp(29)));TextView repo=text(item[1],13,Color.rgb(185,170,195));titleBox.addView(repo,new LinearLayout.LayoutParams(-1,dp(25)));header.addView(titleBox,new LinearLayout.LayoutParams(0,dp(56),1));
            TextView stars=text(item[3].isEmpty()?"":"★ "+item[3],14,Color.rgb(205,195,215));stars.setGravity(Gravity.TOP|Gravity.RIGHT);header.addView(stars,new LinearLayout.LayoutParams(dp(58),dp(28)));card.addView(header);
            TextView desc=text(item[2],14,Color.rgb(220,210,225));desc.setMaxLines(3);desc.setEllipsize(android.text.TextUtils.TruncateAt.END);desc.setPadding(0,dp(10),0,dp(7));card.addView(desc,new LinearLayout.LayoutParams(-1,dp(62)));
            LinearLayout buttons=new LinearLayout(this);buttons.setGravity(Gravity.CENTER_VERTICAL);Button install=control("↓  安装");install.setTextSize(14);install.setTextColor(Color.WHITE);install.setBackground(bg(Color.rgb(210,54,68),22));buttons.addView(install,new LinearLayout.LayoutParams(0,dp(44),1));Button github=control("GitHub");github.setTextSize(14);github.setTextColor(Color.WHITE);github.setBackground(bg(Color.rgb(61,52,70),22));LinearLayout.LayoutParams gp=new LinearLayout.LayoutParams(0,dp(44),1);gp.setMargins(dp(10),0,0,0);buttons.addView(github,gp);card.addView(buttons);
            String repoName=item[1];install.setOnClickListener(v->{Toast.makeText(this,"正在安装 "+item[0]+"…",Toast.LENGTH_SHORT).show();pluginManager.installFromGitHub(repoName,(ok,msg)->runOnUiThread(()->{if(ok)refreshSourceTabs();else showPluginError(msg);Toast.makeText(this,msg,Toast.LENGTH_LONG).show();}));});github.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/"+repoName)));}catch(Exception ignored){}});
        }
        filter.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence x,int a,int c,int d){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence x,int a,int before,int count){String q=x.toString().toLowerCase(Locale.ROOT);for(int i=0;i<data.size();i++){String[] item=data.get(i);cards.get(i).setVisibility((item[0]+item[1]+item[2]).toLowerCase(Locale.ROOT).contains(q)?View.VISIBLE:View.GONE);}}});ScrollView scroll=new ScrollView(this);scroll.addView(list);AlertDialog market=new AlertDialog.Builder(this).setTitle("插件市场 · "+data.size()).setView(scroll).setNeutralButton("刷新目录",null).setNegativeButton("关闭",null).create();market.setOnShowListener(d->market.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v->{market.getButton(AlertDialog.BUTTON_NEUTRAL).setEnabled(false);pluginManager.refreshMarket((ok,msg)->runOnUiThread(()->{if(ok){market.dismiss();showPluginMarket();}else{market.getButton(AlertDialog.BUTTON_NEUTRAL).setEnabled(true);showPluginError(msg);}}));}));market.show();
    }
    private void showPluginDetail(PluginManager.PluginInfo p){
        String state=p.enabled?"已启用":"已停用";
        String[] actions=new String[]{"打开插件主页","插件导航","插件歌单","插件账号",p.enabled?"停用插件":"启用插件","网络权限与设置","删除插件"};
        new AlertDialog.Builder(this).setTitle(p.name+" · "+p.version+" · "+state).setItems(actions,(d,w)->{
            if(w==0){Toast.makeText(this,"正在打开插件主页…",Toast.LENGTH_SHORT).show();pluginManager.page(p.id,"home","",(ok,value)->runOnUiThread(()->showPluginPage(p,ok,value)));}
            else if(w==1)showPluginNavigation(p);
            else if(w==2)showPluginPlaylists(p);
            else if(w==3)showPluginAccount(p);
            else if(w==4){pluginManager.setEnabled(p,!p.enabled);refreshSourceTabs();Toast.makeText(this,p.enabled?"插件已启用":"插件已停用",Toast.LENGTH_SHORT).show();}
            else if(w==5)showPluginSettings(p);else {pluginManager.remove(p);refreshSourceTabs();Toast.makeText(this,"插件已删除",Toast.LENGTH_SHORT).show();}
        }).setNegativeButton("关闭",null).show();
    }
    private void showPluginSettings(PluginManager.PluginInfo p){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(16),dp(8),dp(16),dp(8));Switch network=new Switch(this);network.setText("允许网络访问\n"+p.network.toString());network.setChecked(prefs.getBoolean("plugin_network_"+p.id,false));box.addView(network);SharedPreferences settings=getSharedPreferences("plugin_settings_"+p.id,MODE_PRIVATE);HashMap<String,EditText> inputs=new HashMap<>();for(int i=0;i<p.settings.length();i++){JSONObject spec=p.settings.optJSONObject(i);if(spec==null)continue;String key=spec.optString("key");box.addView(text(spec.optString("label",key),15,Color.WHITE));EditText field=new EditText(this);field.setText(settings.getString(key,""));field.setHint(spec.optString("help",""));box.addView(field);inputs.put(key,field);}ScrollView scroll=new ScrollView(this);scroll.addView(box);new AlertDialog.Builder(this).setTitle(p.name+" · 权限与设置").setView(scroll).setPositiveButton("保存",(d,w)->{prefs.edit().putBoolean("plugin_network_"+p.id,network.isChecked()).apply();SharedPreferences.Editor edit=settings.edit();for(String key:inputs.keySet())edit.putString(key,inputs.get(key).getText().toString());edit.apply();}).setNegativeButton("取消",null).show();}
    private void showPluginNavigation(PluginManager.PluginInfo p){
        if(p.navigationPages.isEmpty()){Toast.makeText(this,"该插件没有自定义导航页面",Toast.LENGTH_SHORT).show();return;}
        String[] labels=p.navigationPages.keySet().toArray(new String[0]);
        new AlertDialog.Builder(this).setTitle(p.name+" · 导航").setItems(labels,(d,w)->{String target=p.navigationPages.get(labels[w]);if(target==null||target.isEmpty()||"home".equals(target)){pluginManager.page(p.id,"home","",(ok,value)->runOnUiThread(()->showPluginPage(p,ok,value)));}else if("liked".equals(target)||"stations".equals(target)||"shows".equals(target)){showPluginBuiltin(p,target);}else{pluginManager.page(p.id,"browse",target,(ok,value)->runOnUiThread(()->showPluginPage(p,ok,value)));}}).setNegativeButton("关闭",null).show();
    }
    private void showPluginBuiltin(PluginManager.PluginInfo p,String target){
        Toast.makeText(this,"正在加载插件页面…",Toast.LENGTH_SHORT).show();
        try{
            if("liked".equals(target)){pluginManager.export(p.id,"liked",new JSONObject().put("offset",0),(ok,value)->runOnUiThread(()->showPluginTrackResult(p,"我喜欢的音乐",ok,value)));return;}
            if("stations".equals(target)){pluginManager.export(p.id,"stations",new JSONObject(),(ok,value)->runOnUiThread(()->{if(!ok){showPluginError(value);return;}try{JSONArray a=new JSONArray(value);ArrayList<String> rows=new ArrayList<>();ArrayList<String> ids=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null){rows.add(x.optString("name",x.optString("title","电台")));ids.add(x.optString("id",""));}}showPluginChoice(p,"私人漫游",rows,ids,"stationNext");}catch(Exception e){showPluginError("电台列表解析失败");}}));return;}
            if("shows".equals(target)){pluginManager.export(p.id,"shows",new JSONObject(),(ok,value)->runOnUiThread(()->{if(!ok){showPluginError(value);return;}try{JSONArray a=new JSONArray(value);ArrayList<String> rows=new ArrayList<>();ArrayList<String> ids=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null){rows.add(x.optString("name",x.optString("title","播客")));ids.add(x.optString("id",""));}}showPluginChoice(p,"我的播客",rows,ids,"show");}catch(Exception e){showPluginError("播客列表解析失败");}}));}
        }catch(Exception e){showPluginError(e.getMessage()==null?"插件页面参数错误":e.getMessage());}
    }
    private void showPluginChoice(PluginManager.PluginInfo p,String title,ArrayList<String> rows,ArrayList<String> ids,String function){
        if(rows.isEmpty()){showPluginError("暂无内容");return;}ListView lv=new ListView(this);lv.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,rows));AlertDialog d=new AlertDialog.Builder(this).setTitle(p.name+" · "+title).setView(lv).setNegativeButton("关闭",null).create();lv.setOnItemClickListener((parent,v,pos,id)->{d.dismiss();try{JSONObject args=new JSONObject().put("id",ids.get(pos));if("show".equals(function))args.put("offset",0);pluginManager.export(p.id,function,args,(ok,value)->runOnUiThread(()->{if("stationNext".equals(function))showPluginTrackResult(p,title,ok,value);else showPluginEpisodeResult(p,title,ok,value);}));}catch(Exception e){showPluginError("插件参数错误");}});d.show();
    }
    private void showPluginEpisodeResult(PluginManager.PluginInfo p,String title,boolean ok,String raw){if(!ok){showPluginError(raw);return;}try{JSONObject root=new JSONObject(raw);JSONArray a=root.optJSONArray("episodes");if(a==null)a=root.optJSONArray("tracks");if(a==null){showPluginPage(p,true,raw);return;}showPluginTrackResult(p,title,true,new JSONObject().put("tracks",a).toString());}catch(Exception e){showPluginError("播客内容解析失败");}}
    private void showPluginTrackResult(PluginManager.PluginInfo p,String title,boolean ok,String raw){if(!ok){showPluginError(raw);return;}try{JSONArray a;try{a=new JSONArray(raw);}catch(Exception e){JSONObject root=new JSONObject(raw);a=root.optJSONArray("tracks");if(a==null)a=root.optJSONArray("episodes");}if(a==null||a.length()==0){showPluginError("暂无歌曲");return;}ArrayList<String> rows=new ArrayList<>();ArrayList<String> ids=new ArrayList<>();ArrayList<String> pics=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject t=a.optJSONObject(i);if(t==null)continue;String name=t.optString("name",t.optString("title","歌曲"));String artist=t.optString("artist","");JSONArray artists=t.optJSONArray("artists");if(artist.isEmpty()&&artists!=null&&artists.length()>0){JSONObject ar=artists.optJSONObject(0);if(ar!=null)artist=ar.optString("name","");}rows.add(name+(artist.isEmpty()?"":"  ·  "+artist));ids.add(t.optString("id",""));String pic=t.optString("imageUrl","");if(pic.isEmpty()){JSONObject album=t.optJSONObject("album");if(album!=null)pic=album.optString("imageUrl","");}pics.add(pic);}ListView lv=new ListView(this);lv.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,rows));AlertDialog d=new AlertDialog.Builder(this).setTitle(p.name+" · "+title).setView(lv).setNegativeButton("关闭",null).create();lv.setOnItemClickListener((parent,v,pos,id)->{d.dismiss();try{Uri u=new Uri.Builder().scheme("plugin").authority(p.id).appendQueryParameter("id",ids.get(pos)).build();pluginTrackRefs.put(u.toString(),p.id+"\n"+ids.get(pos));addRemote(u,rows.get(pos),pics.get(pos));playIndex(tracks.indexOf(u));}catch(Exception e){showPluginError("播放参数错误");}});d.show();}catch(Exception e){showPluginError("插件歌曲解析失败");}}
    private void showPluginError(String message){new AlertDialog.Builder(this).setTitle("插件提示").setMessage(message==null||message.isEmpty()?"插件接口调用失败":message).setPositiveButton("关闭",null).show();}
    private void showPluginAccount(PluginManager.PluginInfo p){
        pluginManager.export(p.id,"account",new JSONObject(),(ok,value)->runOnUiThread(()->showPluginAccountDialog(p,ok,value)));
    }
    private void showPluginAccountDialog(PluginManager.PluginInfo p,boolean ok,String value){
        boolean signed=false;String body="插件账号接口不可用";
        if(ok){body="当前未登录";try{if(value!=null&&!value.trim().isEmpty()&&!"null".equals(value)){JSONObject a=new JSONObject(value);String id=a.optString("id","");String name=a.optString("name","");if(!id.isEmpty()||!name.isEmpty()){signed=true;body="已登录"+(name.isEmpty()?"":"："+name)+(id.isEmpty()?"":"\n账号 ID："+id);}}}catch(Exception ignored){body=value;}}
        final boolean loggedIn=signed; final AlertDialog d=new AlertDialog.Builder(this).setTitle(p.name+" · 账号").setMessage(body).setPositiveButton(loggedIn?"退出登录":"扫码登录",null).setNegativeButton("关闭",null).create();
        d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{d.dismiss();if(loggedIn){pluginManager.export(p.id,"signOut",new JSONObject(),(done,result)->runOnUiThread(()->Toast.makeText(this,done?"已退出插件账号":result,Toast.LENGTH_SHORT).show()));}else{Toast.makeText(this,"正在准备登录二维码…",Toast.LENGTH_SHORT).show();pluginManager.export(p.id,"signIn",new JSONObject(),(done,result)->runOnUiThread(()->{Toast.makeText(this,done?"插件登录成功":result,Toast.LENGTH_LONG).show();if(done)showPluginAccount(p);}));}}));d.show();
    }
    private void addCurrentToSourcePlaylist(){if(current<0||current>=tracks.size())return;Uri track=tracks.get(current);if(!"plugin".equals(track.getScheme())){showPluginError("此歌曲不属于插件音乐源");return;}String source=track.getAuthority();pluginManager.export(source,"playlists",new JSONObject(),(ok,raw)->runOnUiThread(()->{if(!ok){showPluginError(raw);return;}try{JSONArray a=new JSONArray(raw);ArrayList<String> names=new ArrayList<>(),ids=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject item=a.getJSONObject(i);if(item.optBoolean("mine")&&!item.optBoolean("fixed")){names.add(item.optString("name"));ids.add(item.optString("id"));}}if(ids.isEmpty()){showPluginError("请先在这个音乐源创建自己的歌单");return;}new AlertDialog.Builder(this).setTitle("加入来源歌单").setItems(names.toArray(new String[0]),(d,w)->{try{pluginManager.export(source,"addToPlaylist",new JSONObject().put("id",ids.get(w)).put("trackIds",new JSONArray().put(track.getQueryParameter("id"))),(done,result)->runOnUiThread(()->{if(done)Toast.makeText(this,"已加入来源歌单",Toast.LENGTH_SHORT).show();else showPluginError(result);}));}catch(Exception e){showPluginError(e.getMessage());}}).setNegativeButton("取消",null).show();}catch(Exception e){showPluginError("歌单结果解析失败");}}));}
    private void showPluginPlaylists(PluginManager.PluginInfo p){
        pluginManager.export(p.id,"playlists",new JSONObject(),(ok,value)->runOnUiThread(()->{
            if(!ok){showPluginError(value);return;}
            ArrayList<String> rows=new ArrayList<>();ArrayList<String> ids=new ArrayList<>();
            try{if(ok){JSONArray a=new JSONArray(value);for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null){rows.add(x.optString("name",x.optString("title","歌单")));ids.add(x.optString("id",""));}}}}catch(Exception ignored){}
            if(rows.isEmpty())rows.add("暂无插件歌单");
            ListView lv=new ListView(this);lv.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,rows));AlertDialog d=new AlertDialog.Builder(this).setTitle(p.name+" · 歌单").setView(lv).setPositiveButton("新建歌单",null).setNegativeButton("关闭",null).create();
            lv.setOnItemClickListener((parent,v,pos,id)->{if(pos>=ids.size()||ids.get(pos).isEmpty())return;d.dismiss();try{pluginManager.export(p.id,"playlist",new JSONObject().put("id",ids.get(pos)),(loaded,result)->runOnUiThread(()->{if(!loaded){showPluginError(result);return;}showPluginTrackResult(p,rows.get(pos),true,result);}));}catch(Exception e){showPluginError("歌单参数错误");}});
            d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{EditText input=new EditText(this);input.setSingleLine(true);input.setHint("歌单名称");new AlertDialog.Builder(this).setTitle("新建插件歌单").setView(input).setNegativeButton("取消",null).setPositiveButton("创建",(a,b)->{String name=input.getText().toString().trim();if(name.isEmpty())return;try{pluginManager.export(p.id,"createPlaylist",new JSONObject().put("name",name),(created,result)->runOnUiThread(()->Toast.makeText(this,created?"插件歌单已创建":"插件歌单创建失败",Toast.LENGTH_SHORT).show()));}catch(Exception ignored){}}).show();}));d.show();
        }));
    }
    private void showPluginPage(PluginManager.PluginInfo p,boolean ok,String raw){
        if(!ok){showPluginError(raw);return;}try{JSONObject page=new JSONObject(raw);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(12),dp(8),dp(12),dp(8));String subtitle=page.optString("subtitle","");if(!subtitle.isEmpty())box.addView(text(subtitle,14,Color.LTGRAY));JSONArray sections=page.optJSONArray("sections");if(sections==null){if(page.has("tracks")){showPluginTrackResult(p,page.optString("title",p.name),true,raw);return;}throw new Exception("插件没有返回页面内容");}for(int i=0;i<sections.length();i++){JSONObject section=sections.getJSONObject(i);if(section.has("title"))box.addView(text(section.optString("title"),18,Color.WHITE));for(String kind:new String[]{"tracks","albums","playlists","artists","links"}){JSONArray items=section.optJSONArray(kind);if(items==null)continue;for(int j=0;j<items.length();j++){JSONObject item=items.optJSONObject(j);if(item==null)continue;Button button=landscapeButton(item.optString("name",item.optString("title","内容")));button.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);box.addView(button,new LinearLayout.LayoutParams(-1,dp(48)));button.setOnClickListener(v->{try{if(kind.equals("tracks")){showPluginTrackResult(p,"歌曲",true,new JSONObject().put("tracks",new JSONArray().put(item)).toString());return;}if(kind.equals("links")){pluginManager.page(p.id,"browse",item.optString("page"),(loaded,value)->runOnUiThread(()->showPluginPage(p,loaded,value)));return;}String fn=kind.equals("albums")?"album":kind.equals("playlists")?"playlist":"artist";pluginManager.export(p.id,fn,new JSONObject().put("id",item.optString("id")),(loaded,value)->runOnUiThread(()->showPluginTrackResult(p,button.getText().toString(),loaded,value)));}catch(Exception e){showPluginError(e.getMessage());}});}}String more=section.optString("morePage","");if(!more.isEmpty()){Button button=landscapeButton("查看更多");box.addView(button);button.setOnClickListener(v->pluginManager.page(p.id,"browse",more,(loaded,value)->runOnUiThread(()->showPluginPage(p,loaded,value))));}}ScrollView scroll=new ScrollView(this);scroll.addView(box);new AlertDialog.Builder(this).setTitle(page.optString("title",p.name)).setView(scroll).setNegativeButton("关闭",null).show();}catch(Exception e){showPluginError("插件页面解析失败："+e.getMessage());}
    }
    private void showMore(){new AlertDialog.Builder(this).setTitle("内容浏览").setItems(new String[]{"推荐","评论","歌手","专辑","播客","最近播放","插件","账号与设置","备份与恢复"},(d,w)->{if(w==0)showRecommendations();else if(w==1)showComments();else if(w==2)showArtists();else if(w==3)showAlbums();else if(w==4)showPodcast();else if(w==5)showRecent();else if(w==6)showPlugins();else if(w==7)showAccountSettings();else showBackup();}).setNegativeButton("关闭",null).show();}
    private void loadCovers(){try{JSONObject o=new JSONObject(prefs.getString("covers","{}"));java.util.Iterator<String> it=o.keys();while(it.hasNext()){String k=it.next();covers.put(k,o.optString(k,""));}}catch(Exception ignored){}}
    private void saveCovers(){try{JSONObject o=new JSONObject();for(String k:covers.keySet())o.put(k,covers.get(k));prefs.edit().putString("covers",o.toString()).apply();}catch(Exception ignored){}}
    private void loadLocalLyrics(){try{JSONObject o=new JSONObject(prefs.getString("local_lyrics","{}"));java.util.Iterator<String> it=o.keys();while(it.hasNext()){String k=it.next();localLyrics.put(k,o.optString(k,""));}}catch(Exception ignored){}}
    private void saveLocalLyrics(){try{JSONObject o=new JSONObject();for(String k:localLyrics.keySet())o.put(k,localLyrics.get(k));prefs.edit().putString("local_lyrics",o.toString()).apply();}catch(Exception ignored){}}
    private void readLocalLyrics(Uri uri){if(uri==null||current<0||current>=tracks.size())return;try{InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream buf=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))>0)buf.write(b,0,n);in.close();String lrc=new String(buf.toByteArray(),"UTF-8");localLyrics.put(tracks.get(current).toString(),lrc);saveLocalLyrics();Toast.makeText(this,"本地歌词已导入",Toast.LENGTH_SHORT).show();showLyricsText(names.get(current),lrc);}catch(Exception e){Toast.makeText(this,"歌词文件读取失败",Toast.LENGTH_SHORT).show();}}
    private void loadCover(Uri uri){if(coverArt==null)return;coverArt.setImageResource(com.mygo.music.R.drawable.ic_launcher);String cu=covers.get(uri.toString());Executors.newSingleThreadExecutor().execute(()->{try{Bitmap b=null;if(cu!=null&&!cu.isEmpty())b=BitmapFactory.decodeStream(new URL(cu).openStream());else{MediaMetadataRetriever r=new MediaMetadataRetriever();r.setDataSource(this,uri);byte[] data=r.getEmbeddedPicture();if(data!=null)b=BitmapFactory.decodeByteArray(data,0,data.length);r.release();}Bitmap result=b;if(result!=null)runOnUiThread(()->coverArt.setImageBitmap(result));}catch(Exception ignored){}});}
    private void addRemote(Uri u,String name,String pic){runOnUiThread(()->{if(tracks.contains(u))return;tracks.add(u);names.add(name);if(pic!=null&&!pic.isEmpty())covers.put(u.toString(),pic);saveLibrary();saveCovers();adapter.notifyDataSetChanged();refreshLandscapeGrid();if(headingView!=null)headingView.setText("本地歌曲  ·  "+names.size());});}
    private void loadComments(){try{JSONObject all=new JSONObject(prefs.getString("comments","{}"));java.util.Iterator<String> it=all.keys();while(it.hasNext()){String k=it.next();JSONArray a=all.getJSONArray(k);ArrayList<String> v=new ArrayList<>();for(int i=0;i<a.length();i++)v.add(a.getString(i));comments.put(k,v);}}catch(Exception ignored){}}
