    private void showRecommendations(){if(names.isEmpty()){Toast.makeText(this,"添加一些歌曲后才能生成推荐",Toast.LENGTH_SHORT).show();return;}ArrayList<String> ns=new ArrayList<>(names);Collections.shuffle(ns);ListView lv=new ListView(this);lv.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,ns));AlertDialog d=new AlertDialog.Builder(this).setTitle("推荐给你").setView(lv).setNegativeButton("关闭",null).create();lv.setOnItemClickListener((p,v,pos,id)->{String n=ns.get(pos);playIndex(names.indexOf(n));d.dismiss();});d.show();}
    private void showComments(){
        if(current<0||current>=tracks.size()){Toast.makeText(this,"请先播放一首歌曲",Toast.LENGTH_SHORT).show();return;}
        String key=tracks.get(current).toString(); String pluginRef=pluginTrackRefs.get(key);
        if(pluginRef!=null){String[] parts=pluginRef.split("\\n",2);showPluginComments(parts[0],parts.length>1?parts[1]:"",names.get(current));return;}
        ArrayList<String> list=comments.get(key);if(list==null){list=new ArrayList<>();comments.put(key,list);}final ArrayList<String> rows=list;ListView lv=new ListView(this);lv.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,rows));AlertDialog d=new AlertDialog.Builder(this).setTitle(names.get(current)+" · 评论").setView(lv).setPositiveButton("写评论",null).setNegativeButton("关闭",null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{final EditText input=new EditText(this);input.setHint("写下评论");new AlertDialog.Builder(this).setTitle("发表评论").setView(input).setNegativeButton("取消",null).setPositiveButton("发布",(a,b)->{String t=input.getText().toString().trim();if(!t.isEmpty()){rows.add(t);saveComments();lv.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,rows));}}).show();}));d.show();
    }
    private void showPluginComments(String pluginId,String trackId,String title){
        Toast.makeText(this,"正在获取插件评论…",Toast.LENGTH_SHORT).show();
        pluginManager.comments(pluginId,trackId,(ok,value)->runOnUiThread(()->{
            ArrayList<String> rows=new ArrayList<>();
            try{if(ok){JSONObject root=new JSONObject(value);JSONArray a=root.optJSONArray("comments");if(a!=null)for(int i=0;i<a.length();i++){JSONObject c=a.optJSONObject(i);if(c!=null)rows.add(c.optString("author","用户")+"："+c.optString("text",c.optString("content","")));}}}catch(Exception ignored){}
            ListView lv=new ListView(this);lv.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,rows));AlertDialog d=new AlertDialog.Builder(this).setTitle(title+" · 评论").setView(lv).setPositiveButton("写评论",null).setNegativeButton("关闭",null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{EditText input=new EditText(this);input.setHint("写下评论");new AlertDialog.Builder(this).setTitle("发表评论").setView(input).setNegativeButton("取消",null).setPositiveButton("发布",(a,b)->{String t=input.getText().toString().trim();if(t.isEmpty())return;pluginManager.postComment(pluginId,trackId,t,(posted,result)->runOnUiThread(()->{if(!posted){showPluginError(result);return;}rows.add(t);lv.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,rows));Toast.makeText(this,"评论已发布",Toast.LENGTH_SHORT).show();}));}).show();}));d.show();
        }));
    }
    private void loadRecent(){String raw=prefs.getString("recent","");if(!raw.isEmpty())recentUris.addAll(Arrays.asList(raw.split("\n")));}
